import json, base64, csv, html
import numpy as np
from model import SP, SPD, COMP, F_RT, LIG

R = json.load(open('/home/claude/pb/results.json'))
png = base64.b64encode(open('/home/claude/pb/pourbaix_CuFe_joint.png', 'rb').read()).decode()

DISP = {
 'Cu2+': 'Cu²⁺', 'CuCit-': 'CuCit⁻', 'CuGly2': 'Cu(Gly)₂', 'Cu(OH)2s': 'Cu(OH)₂(s)', 'Cu(OH)4^2-': 'Cu(OH)₄²⁻',
 'CuCl2-': 'CuCl₂⁻', 'Cu(NH3)2+': 'Cu(NH₃)₂⁺', 'Cu2O': 'Cu₂O(s)', 'Cu(s)': 'Cu(s)',
 'Fe3+': 'Fe³⁺', 'FeCit': 'FeCit(aq) = [Fe(Hcit)]', 'Fe(Cit)2^3-': '[Fe(Hcit)₂]³⁻', 'Fe(Cit)2H-1^4-': '[Fe(cit)(Hcit)]⁴⁻',
 'Fe(Cit)2H-2^5-': '[Fe(cit)₂]⁵⁻', 'Fe(OH)4-': 'Fe(OH)₄⁻', 'Fe2+': 'Fe²⁺', 'FeCit-': 'FeCit⁻', 'FeGly2': 'Fe(Gly)₂',
 'Fe(OH)2s': 'Fe(OH)₂(s)', 'Fe(s)': 'Fe(s)'}
def D(n): return DISP.get(n, SPD[n].label if n in SPD else n)
CNAME = {'Cu': 'Cu²⁺', 'Fe': 'Fe³⁺', 'Cit': 'Cit³⁻', 'Gly': 'Gly⁻', 'Cl': 'Cl⁻', 'NH3': 'NH₃', 'H': 'H⁺', 'e': 'e⁻'}

def reaction(s):
    lhs = []
    for c, v in s['stoich'].items():
        if c == 'H' and v < 0: continue
        lhs.append(f"{'' if v == 1 else f'{v:g} '}{CNAME[c]}")
    rhs = [s['label']]
    nh = s['stoich'].get('H', 0)
    if nh < 0:
        lhs.append(f"{'' if -nh == 1 else f'{-nh:g} '}H₂O"); rhs.append(f"{'' if -nh == 1 else f'{-nh:g} '}H⁺")
    return ' + '.join(lhs) + ' ⇌ ' + ' + '.join(rhs)

def eq_text(c):
    """clean equation from coefficient dict: dlogK - dnuH*pH - dnue*pe + sum dnuL*log[L] = 0"""
    terms = []
    def add(coef, name):
        if abs(coef) > 1e-9: terms.append((coef, name))
    if abs(c['dnu_e']) > 1e-9:
        ne = c['dnu_e']
        const = F_RT * c['dlogK'] / ne
        s = f"E = {const:+.4f}"
        add(-F_RT * c['dnu_H'] / ne, 'pH')
        for L in LIG: add(F_RT * c[f'dnu_{L}'] / ne, f'log[{L}]')
        for coef, name in terms: s += f" {'−' if coef < 0 else '+'} {abs(coef):.4f}·{name}"
        return s.replace('= +', '= ') + '  (V vs SHE)'
    elif abs(c['dnu_H']) > 1e-9:
        nh = c['dnu_H']
        s = f"pH = {c['dlogK']/nh:.3f}"
        for L in LIG:
            coef = c[f'dnu_{L}'] / nh
            if abs(coef) > 1e-9: s += f" {'−' if coef < 0 else '+'} {abs(coef):g}·log[{L}]"
        return s
    else:
        s = ''
        for L in LIG:
            coef = c[f'dnu_{L}']
            if abs(coef) > 1e-9: s += f" {'−' if coef < 0 else '+'} {abs(coef):g}·log[{L}]"
        return s.strip().lstrip('+ ').strip() + f" = {-c['dlogK']:.3f}  (pH enters through the free-ligand terms)"

def merge_junctions(J):
    J = sorted(J, key=lambda j: (j['pH'], j['E']))
    out = []
    for j in J:
        for o in out:
            if set(j['species']) & set(o['species']) and abs(j['pH'] - o['pH']) < 0.2 and abs(j['E'] - o['E']) < 0.03:
                n = o['n'] + 1
                o['pH'] = (o['pH'] * o['n'] + j['pH']) / n; o['E'] = (o['E'] * o['n'] + j['E']) / n
                o['species'] = sorted(set(o['species']) | set(j['species'])); o['n'] = n
                break
        else:
            out.append({'pH': j['pH'], 'E': j['E'], 'species': list(j['species']), 'n': 1})
    return sorted(out, key=lambda j: j['pH'])

JUNC = {m: merge_junctions(R['results'][m]['junctions']) for m in ('Cu', 'Fe')}

# ------------------------------------------------------------------ CSV exports
with open('/mnt/user-data/outputs/pourbaix_constants_used.csv', 'w', newline='') as f:
    w = csv.writer(f)
    w.writerow(['species', 'formula', 'metal', 'oxidation_state', 'phase', 'formation_reaction_from_components',
                'logK_used_I0.1_conc_scale', 'logK_input', 'input_basis', 'source', 'note'])
    for s in R['species']:
        w.writerow([s['name'], s['label'], s['metal'] or '', s['ox'], s['phase'], reaction(s),
                    f"{s['logK_used']:.3f}", f"{s['logK_input']:.3f}", 'I=0.1 (as given)' if s['basis'] == 'c' else 'I=0, Davies-corrected',
                    s['ref'], s['note']])
with open('/mnt/user-data/outputs/pourbaix_boundaries_junctions.csv', 'w', newline='') as f:
    w = csv.writer(f)
    w.writerow(['metal', 'record', 'species_A', 'species_B', 'species_C', 'type', 'pH_min', 'pH_max', 'E_min_V', 'E_max_V',
                'equation_from_solver_constants', 'sample_points_pH_E'])
    for m in ('Cu', 'Fe'):
        for b in R['results'][m]['boundaries']:
            samp = '; '.join(f"({p:.2f}, {e:+.3f})" for p, e in b['samples']) if b['redox'] else f"pH = {b['pH_median']:.2f}"
            w.writerow([m, 'boundary', D(b['A']), D(b['B']), '', b['equation']['kind'], f"{b['pH_min']:.2f}", f"{b['pH_max']:.2f}",
                        f"{b['E_min']:.3f}", f"{b['E_max']:.3f}", eq_text(b['equation']), samp])
        for j in JUNC[m]:
            sp = [D(x) for x in j['species']]
            w.writerow([m, 'junction'] + sp[:3] + [' + '.join(sp[3:]) if len(sp) > 3 else 'triple point', f"{j['pH']:.2f}", '', f"{j['E']:.3f}", '', '', ''])

# ------------------------------------------------------------------ HTML
def tr(cells, head=False):
    t = 'th' if head else 'td'
    return '<tr>' + ''.join(f'<{t}>{c}</{t}>' for c in cells) + '</tr>'

def table(headers, rows, cls=''):
    return f'<div class="tw"><table class="{cls}">' + '<thead>' + tr(headers, True) + '</thead><tbody>' + ''.join(tr(r) for r in rows) + '</tbody></table></div>'

# regions
def region_rows(m):
    rows = []
    for r in R['results'][m]['regions']:
        s = SPD[r['species']]
        rows.append([D(r['species']), {0: 'metal', 1: 'Cu(I)', 2: 'Cu(II)' if m == 'Cu' else 'Fe(II)', 3: 'Fe(III)'}[s.ox],
                     'solid' if s.phase == 's' else 'aqueous', f"{r['pH_range'][0]:.2f} – {r['pH_range'][1]:.2f}",
                     f"{r['E_range'][0]:+.3f} – {r['E_range'][1]:+.3f}", f"{100*r['area_frac']:.1f} %"])
    return rows

def boundary_rows(m):
    rows = []
    B = sorted(R['results'][m]['boundaries'], key=lambda b: (b['pH_min'], b['E_min']))
    for b in B:
        if b['redox']:
            samp = ', '.join(f"({p:.2f}, {e:+.3f})" for p, e in b['samples'][::max(1, (len(b['samples']) - 1) // 2)][:3])
            span = f"pH {b['pH_min']:.2f}–{b['pH_max']:.2f}; E {b['E_min']:+.3f}…{b['E_max']:+.3f}"
        else:
            samp = f"pH = {b['pH_median']:.2f}"
            span = f"E {b['E_min']:+.3f}…{b['E_max']:+.3f}"
        rows.append([f"{D(b['A'])} | {D(b['B'])}", b['equation']['kind'].split(' (')[0], span, f"<code>{eq_text(b['equation'])}</code>", samp])
    return rows

def junction_rows(m):
    return [[' / '.join(D(s) for s in j['species']), f"{j['pH']:.2f}", f"{j['E']:+.3f}", 'near-degenerate cluster (two triple points within ~1 grid cell)' if len(j['species']) > 3 else ''] for j in JUNC[m]]

def sub_rows(key):
    rows = []
    for r in R['substate'][key]:
        rows.append([f"{r['pH']:g}", ', '.join(f"{lab} {pct:g} %" for lab, pct in r['top']),
                     ' '.join(f"{L} {v:+.2f}" for L, v in r['logL'].items())])
    return rows

def species_rows():
    rows = []
    for s in R['species']:
        grp = 'ligand / water' if s['metal'] is None else f"{s['metal']}({s['ox']})" if s['ox'] else f"{s['metal']}(0)"
        rows.append([grp, s['label'], reaction(s), f"{s['logK_used']:.3f}",
                     ('as compiled at I = 0.1' if s['basis'] == 'c' else f"I = 0 value {s['logK_input']:.3f}, Davies → I = 0.1"),
                     html.escape(s['ref']) + (f" — <em>{html.escape(s['note'])}</em>" if s['note'] else '')])
    return rows

dep = R['deposition']
dep_rows = []
for (p, ecu), (_, efe) in zip(dep['Cu(s) top edge'], dep['Fe(s) top edge']):
    dep_rows.append([f"{p:g}", f"{ecu:+.3f}", f"{efe:+.3f}", f"{ecu-efe:.2f}", f"{-F_RT*p:+.3f}", f"{efe + F_RT*p:+.3f}"])

sens = list(R['sensitivity'].values())[0]
sens_txt = ' → '.join(f"{D(n)} (pH {a:.2f}–{b:.2f})" for n, a, b in sens)

CSS = """
